package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.io.StringBuffer;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class HelpFormatter_renderWrappedText_TriageGen1Test {

    private HelpFormatter formatter;

    @Before
    public void setUp() {
        formatter = new HelpFormatter();
        formatter.setWidth(30);
    }

    @Test
    public void testRenderWrappedText_EmptyString() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "");
        assertEquals("", sb.toString());
    }

    @Test
    public void testRenderWrappedText_SingleWord() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "word");
        assertEquals("word", sb.toString());
    }

    @Test
    public void testRenderWrappedText_SingleWordWithSpaces() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "word ");
        assertEquals("word", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MultipleWordsNoWrap() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 20, 4, "This is a test");
        assertEquals("This is a test", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MultipleWordsWrap() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "This is a test");
        assertEquals("This is a\n    test", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WrapWithNextLineTabStop() {
        StringBuffer sb = new StringBuffer();
        formatter.setNewLine("\n");
        formatter.renderWrappedText(sb, 10, 4, "This is a test");
        assertEquals("This is a\n    test", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WrapWithCustomNewLine() {
        StringBuffer sb = new StringBuffer();
        formatter.setNewLine(" | ");
        formatter.renderWrappedText(sb, 10, 4, "This is a test");
        assertEquals("This is a |    test", sb.toString());
    }

    @Test
    public void testRenderWrappedText_ExactWidth() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 15, 4, "ExactlyFifteen");
        assertEquals("ExactlyFifteen", sb.toString());
    }

    @Test
    public void testRenderWrappedText_PaddingWithNextLineTabStop() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "Line1\nLine2");
        assertEquals("Line1\n    Line2", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MultipleLines() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "Line1\nLine2\nLine3");
        assertEquals("Line1\n    Line2\n    Line3", sb.toString());
    }

    @Test
    public void testRenderWrappedText_SpecialCharacters() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "Line1!\nLine2?");
        assertEquals("Line1!\n    Line2?", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WhitespaceHandling() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "   Leading and trailing   ");
        assertEquals("Leading and\n    trailing", sb.toString());
    }

    @Test
    public void testRenderWrappedText_LeadingSpaces() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "   Leading spaces");
        assertEquals("Leading\n    spaces", sb.toString());
    }

    @Test
    public void testRenderWrappedText_TrailingSpaces() {
        StringBuffer sb = new StringBuffer();
        formatter.renderWrappedText(sb, 10, 4, "Trailing spaces   ");
        assertEquals("Trailing\n    spaces", sb.toString());
    }
}
